731	<script>
732	  // ── CONFIG ──────────────────────────────────────────────────────────────
733	  const API_BASE = 'http://localhost:8000';
734	  let selectedCommunity = null;
735	  let allCommunities = [];
736	  let currentStartup = null;
737	
738	  // ── FIND COMMUNITIES ─────────────────────────────────────────────────────
739	  async function findCommunities() {
740	    const name = document.getElementById('startup-name').value.trim();
741	    const desc = document.getElementById('startup-desc').value.trim();
742	    const customer = document.getElementById('startup-customer').value.trim();
743	    const stage = document.getElementById('startup-stage').value;
744	    const category = document.getElementById('startup-category').value;
745	
746	    if (!name || !desc || !customer) {
747	      alert('Please fill in all fields to find your communities.');
748	      return;
749	    }
750	
751	    currentStartup = { name, description: desc, target_customer: customer, stage, category };
752	
753	    // Show loader
754	    document.getElementById('find-btn').disabled = true;
755	    document.getElementById('find-loader').style.display = 'flex';
756	    document.getElementById('results-section').style.display = 'none';
757	    document.getElementById('empty-state').style.display = 'none';
758	    document.getElementById('stats-row').style.display = 'none';
759	    document.getElementById('playbook-area').classList.remove('visible');
760	
761	    try {
762	      const res = await fetch(`${API_BASE}/find-communities`, {
763	        method: 'POST',
764	        headers: { 'Content-Type': 'application/json' },
765	        body: JSON.stringify(currentStartup)
766	      });
767	
768	      if (!res.ok) throw new Error(await res.text());
769	      const data = await res.json();
770	      allCommunities = data.communities;
771	
772	      renderCommunities(allCommunities);
773	      renderStats(allCommunities);
774	
775	    } catch (err) {
776	      console.error(err);
777	      alert('Error connecting to API. Make sure the backend is running on port 8000.\n\n' + err.message);
778	    } finally {
779	      document.getElementById('find-btn').disabled = false;
780	      document.getElementById('find-loader').style.display = 'none';
781	    }
782	  }
783	
784	  // ── RENDER COMMUNITY LIST ────────────────────────────────────────────────
785	  function renderCommunities(communities) {
786	    const list = document.getElementById('community-list');
787	    document.getElementById('match-count').textContent = communities.length;
788	    list.innerHTML = '';
789	
790	    communities.forEach((c, i) => {
791	      const score = c.relevance_score || 85;
792	      const scoreClass = score >= 80 ? '' : score >= 60 ? 'medium' : 'low';
793	
794	      const card = document.createElement('div');
795	      card.className = 'community-card';
796	      card.dataset.index = i;
797	      card.innerHTML = `
798	        <div class="card-top">
799	          <div>
800	            <div class="card-platform">${c.platform}</div>
801	            <div class="card-name">${c.name}</div>
802	          </div>
803	          <div class="score-badge ${scoreClass}">${score}%</div>
804	        </div>
805	        <div class="card-icp">${c.icp_match || c.approach || ''}</div>
806	        <div class="card-meta">
