808	          <div class="meta-pill">⚡ ${c.engagement_level || 'High'}</div>
809	          <div class="meta-pill">⏱ ${c.time_to_first_customer || '3-7 days'}</div>
810	        </div>
811	        <button class="btn-generate-playbook" onclick="generatePlaybook(${i}, event)">
812	          Generate Activation Playbook →
813	        </button>
814	      `;
815	      card.addEventListener('click', () => selectCommunity(i, card));
816	      list.appendChild(card);
817	    });
818	
819	    document.getElementById('results-section').style.display = 'block';
820	  }
821	
822	  // ── RENDER STATS ROW ─────────────────────────────────────────────────────
823	  function renderStats(communities) {
824	    const statsRow = document.getElementById('stats-row');
825	    statsRow.style.display = 'grid';
826	
827	    document.getElementById('s1').textContent = communities.length;
828	
829	    // Estimate total audience
830	    let totalM = communities.length * 180;
831	    document.getElementById('s2').textContent = totalM > 1000 ? `${(totalM/1000).toFixed(1)}M+` : `${totalM}K+`;
832	
833	    // Fastest
834	    const fastest = communities
835	      .map(c => c.time_to_first_customer || '7 days')
836	      .sort((a,b) => parseInt(a) - parseInt(b))[0];
837	    document.getElementById('s3').textContent = fastest || '3-5 days';
838	
839	    // Top platform
840	    const platforms = communities.map(c => c.platform);
841	    const topPlatform = platforms.sort((a,b) =>
842	      platforms.filter(v => v===b).length - platforms.filter(v => v===a).length
843	    )[0];
844	    document.getElementById('s4').textContent = topPlatform || 'Reddit';
845	  }
846	
847	  // ── SELECT COMMUNITY ─────────────────────────────────────────────────────
848	  function selectCommunity(index, cardEl) {
849	    document.querySelectorAll('.community-card').forEach(c => c.classList.remove('active'));
850	    cardEl.classList.add('active');
851	    selectedCommunity = allCommunities[index];
852	
853	    // Show preview in playbook area without generating
854	    const playbook = document.getElementById('playbook-area');
855	    const content = document.getElementById('playbook-content');
856	    playbook.classList.add('visible');
857	
858	    content.innerHTML = `
859	      <div class="playbook-header">
860	        <div class="playbook-title">${selectedCommunity.name}</div>
861	        <span class="playbook-platform-tag">${selectedCommunity.platform}</span>
862	      </div>
863	      <p style="color:var(--text2); margin-bottom:20px; font-size:15px; line-height:1.6;">
864	        ${selectedCommunity.icp_match || selectedCommunity.approach || 'This community matches your target audience.'}
865	      </p>
866	      <p style="color:var(--text3); font-size:14px;">
867	        Click <strong style="color:var(--accent)">Generate Activation Playbook</strong> on the community card to get your step-by-step GTM plan for this channel.
868	      </p>
869	    `;
870	  }
871	
872	  // ── GENERATE PLAYBOOK ────────────────────────────────────────────────────
873	  async function generatePlaybook(index, event) {
874	    event.stopPropagation();
875	    if (!currentStartup) return;
876	
877	    const community = allCommunities[index];
878	    selectedCommunity = community;
879	
880	    // Mark active
881	    document.querySelectorAll('.community-card').forEach((c, i) => {
882	      c.classList.toggle('active', i === index);
883	    });
884	
885	    const playbook = document.getElementById('playbook-area');
886	    const content = document.getElementById('playbook-content');
887	    playbook.classList.add('visible');
888	
889	    content.innerHTML = `
890	      <div class="playbook-loader">
891	        <div class="spinner"></div>
892	        <div class="loader-text">Generating your playbook for ${community.name}...</div>
893	        <div class="loader-sub">Crafting your first post, DM templates and weekly action plan</div>
894	      </div>
895	    `;
896	
897	    try {
898	      const res = await fetch(`${API_BASE}/generate-playbook`, {
899	        method: 'POST',
900	        headers: { 'Content-Type': 'application/json' },
901	        body: JSON.stringify({
902	          startup: currentStartup,
903	          community_name: community.name,
904	          community_platform: community.platform,
905	          community_description: community.icp_match || ''
906	        })
907	      });
908	
909	      if (!res.ok) throw new Error(await res.text());
910	      const data = await res.json();
911	      renderPlaybook(data, community);
912	
913	    } catch (err) {
914	      content.innerHTML = `<div style="padding:40px;color:var(--red);">Error generating playbook: ${err.message}</div>`;
915	    }
916	  }
