922	    const week1Html = (p.week1_actions || []).map(a =>
923	      `<li>${a}</li>`
924	    ).join('');
925	
926	    const dosHtml = (p.dos || []).map(d => `<li>${d}</li>`).join('');
927	    const dontsHtml = (p.donts || []).map(d => `<li>${d}</li>`).join('');
928	
929	    content.innerHTML = `
930	      <div class="playbook-header">
931	        <div class="playbook-title">${p.community || community.name}</div>
932	        <span class="playbook-platform-tag">${p.platform || community.platform}</span>
933	      </div>
934	
935	      <div class="playbook-grid">
936	
937	        <!-- Week 1 Actions -->
938	        <div class="playbook-card">
939	          <div class="card-header">📅 Week 1 Action Plan</div>
940	          <ul class="action-list">${week1Html}</ul>
941	        </div>
942	
943	        <!-- KPIs -->
944	        <div class="playbook-card">
945	          <div class="card-header">🎯 Targets</div>
946	          <div class="kpi-row">
947	            <div class="kpi-item">
948	              <div class="kpi-label">Week 1 Goal</div>
949	              <div class="kpi-value">${p.kpis?.week1_target || '10 replies, 3 DMs'}</div>
950	            </div>
951	            <div class="kpi-item">
952	              <div class="kpi-label">Conversion Goal</div>
953	              <div class="kpi-value">${p.kpis?.conversion_goal || '5 beta signups'}</div>
954	            </div>
955	          </div>
956	
957	          <div style="margin-top:16px;">
958	            <div class="card-header">Do's & Don'ts</div>
959	            <div class="dos-donts">
960	              <ul class="do-list">${dosHtml}</ul>
961	              <ul class="dont-list">${dontsHtml}</ul>
962	            </div>
963	          </div>
964	        </div>
965	
966	        <!-- First Post -->
967	        <div class="playbook-card full">
968	          <div class="card-header">📝 Your First Post (Copy & Paste Ready)</div>
969	          <div class="post-preview">
970	            <div class="post-title">${p.first_post?.title || 'Post title'}</div>
971	            <div class="post-body">${p.first_post?.body || ''}</div>
972	            <span class="post-type-tag">${p.first_post?.post_type || 'discussion'}</span>
973	          </div>
974	        </div>
975	
976	        <!-- DM Template -->
977	        <div class="playbook-card full">
978	          <div class="card-header">💬 DM Template (For Engaged Members)</div>
979	          <div class="dm-template">${p.first_dm_template || ''}</div>
980	        </div>
981	
982	        <!-- Insider Tip -->
983	        <div class="playbook-card full">
984	          <div class="insider-tip">${p.insider_tip || ''}</div>
985	        </div>
986	
987	      </div>
988	    `;
989	  }
