361	const API_BASE = 'http://localhost:8000';
362	let currentStartup = null;
363	let currentCommunities = [];
364	
365	function goToScreen(id) {
366	  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
367	  document.getElementById(id).classList.add('active');
368	}
369	
370	async function findCommunities() {
371	  currentStartup = {
372	    name: document.getElementById('s-name').value.trim(),
373	    description: document.getElementById('s-desc').value.trim(),
374	    target_customer: document.getElementById('s-customer').value.trim(),
375	    stage: document.getElementById('s-stage').value,
376	    category: document.getElementById('s-category').value,
377	  };
378	  if (!currentStartup.name || !currentStartup.description || !currentStartup.target_customer) {
379	    alert('Please fill in all fields.');
380	    return;
381	  }
382	
383	  const btn = document.getElementById('find-btn');
384	  btn.disabled = true;
385	  btn.textContent = 'Scanning 2,847 communities...';
386	
387	  try {
388	    const res = await fetch(`${API_BASE}/find-communities`, {
389	      method: 'POST',
390	      headers: { 'Content-Type': 'application/json' },
391	      body: JSON.stringify(currentStartup),
392	    });
393	    if (!res.ok) throw new Error(await res.text());
394	    const data = await res.json();
395	    currentCommunities = data.communities;
396	    renderMap(currentCommunities);
397	    goToScreen('screen-map');
398	  } catch (err) {
399	    alert('Error connecting to API. Is the backend running on port 8000?\n\n' + err.message);
400	  } finally {
401	    btn.disabled = false;
402	    btn.textContent = 'Map My Network →';
403	  }
